<?php
if (!defined('ABSPATH')) exit;
function pid_uganda_setup(){load_theme_textdomain('pid-uganda',get_template_directory().'/languages');add_theme_support('title-tag');add_theme_support('post-thumbnails');add_theme_support('custom-logo',array('height'=>100,'width'=>240,'flex-height'=>true,'flex-width'=>true));add_theme_support('html5',array('search-form','comment-form','comment-list','gallery','caption','style','script'));register_nav_menus(array('primary'=>__('Primary Navigation','pid-uganda'),'footer'=>__('Footer Navigation','pid-uganda')));}
add_action('after_setup_theme','pid_uganda_setup');
function pid_uganda_assets(){wp_enqueue_style('pid-uganda-style',get_stylesheet_uri(),array(),'1.0.0');wp_enqueue_script('pid-uganda-navigation',get_template_directory_uri().'/assets/navigation.js',array(),'1.0.0',true);}
add_action('wp_enqueue_scripts','pid_uganda_assets');
function pid_uganda_register_content(){register_post_type('pid_program',array('labels'=>array('name'=>__('PID Programmes','pid-uganda'),'singular_name'=>__('Programme','pid-uganda'),'add_new_item'=>__('Add Programme','pid-uganda'),'edit_item'=>__('Edit Programme','pid-uganda')),'public'=>true,'has_archive'=>true,'show_in_rest'=>true,'menu_icon'=>'dashicons-groups','rewrite'=>array('slug'=>'programmes'),'supports'=>array('title','editor','excerpt','thumbnail','revisions')));}
add_action('init','pid_uganda_register_content');
function pid_uganda_customize_register($c){$c->add_section('pid_home',array('title'=>__('PID Homepage','pid-uganda'),'priority'=>30));$fields=array('pid_tagline'=>array('Website tagline','Empowering Grassroots Communities Through Sport, Health & Sustainable Livelihoods','text'),'pid_announcement'=>array('Registration / announcement line','Official Registered NGO Reg No: INDR177427311NB | Kitintale, Kampala','text'),'pid_hero_title'=>array('Hero heading','Empowering Grassroots Communities in Uganda Through Sports, Health & Sustainable Livelihoods','text'),'pid_hero_description'=>array('Hero description','Partnership for Integrated Development Uganda (PID) is a registered NGO dedicated to improving lives of vulnerable youth, children, and women through community-led solutions.','textarea'),'pid_hero_image'=>array('Hero image URL','', 'url'),'pid_about_image'=>array('About image URL','', 'url'),'pid_about_title'=>array('About heading','About PID Uganda','text'),'pid_about_text'=>array('About text','Established in 2010 in Kitintale, Kampala, PID works with local leaders, schools and families.','textarea'),'pid_contact_email'=>array('Contact email','info@piduganda.org','text'),'pid_contact_phone'=>array('Contact phone','+256 776 526 344','text'),'pid_contact_location'=>array('Contact location','Kitintale, Kampala, Uganda','text'));foreach($fields as $id=>$f){$c->add_setting($id,array('default'=>$f[1],'sanitize_callback'=>$f[2]==='url'?'esc_url_raw':($f[2]==='textarea'?'sanitize_textarea_field':'sanitize_text_field')));$c->add_control($id,array('label'=>__($f[0],'pid-uganda'),'section'=>'pid_home','type'=>$f[2]));}}
add_action('customize_register','pid_uganda_customize_register');
function pid_uganda_import_menu(){add_theme_page(__('PID Content Import','pid-uganda'),__('PID Content Import','pid-uganda'),'manage_options','pid-content-import','pid_uganda_import_page');}
add_action('admin_menu','pid_uganda_import_menu');
function pid_uganda_import_page(){if(!current_user_can('manage_options'))return;$message='';if(isset($_POST['pid_import_nonce'])&&wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['pid_import_nonce'])),'pid_import_content')&&!empty($_FILES['pid_json']['tmp_name'])){$f=$_FILES['pid_json'];if(!empty($f['error'])||!is_uploaded_file($f['tmp_name'])||strtolower(pathinfo($f['name'],PATHINFO_EXTENSION))!=='json'||(int)$f['size']>5*MB_IN_BYTES){$message='Upload a valid JSON file smaller than 5 MB.';}else{$data=json_decode(file_get_contents($f['tmp_name']),true);if(!is_array($data)){$message='Invalid JSON. Upload src/config/siteContent.json from the original repository.';}else{$count=0;foreach(($data['services']??array()) as $s){if(empty($s['title']))continue;$key=sanitize_key($s['id']??sanitize_title($s['title']));$old=get_posts(array('post_type'=>'pid_program','post_status'=>'any','meta_key'=>'_pid_source_id','meta_value'=>$key,'numberposts'=>1));$p=array('post_type'=>'pid_program','post_status'=>'publish','post_title'=>sanitize_text_field($s['title']),'post_content'=>wp_kses_post(wpautop($s['description']??'')),'post_excerpt'=>sanitize_text_field($s['category']??''));if($old)$p['ID']=$old[0]->ID;$id=wp_insert_post($p,true);if(!is_wp_error($id)){update_post_meta($id,'_pid_source_id',$key);update_post_meta($id,'_pid_category',sanitize_text_field($s['category']??''));$count++;}}$set=$data['siteSettings']??array();if(!empty($set['siteTagline']))set_theme_mod('pid_tagline',sanitize_text_field($set['siteTagline']));if(!empty($set['announcementText']))set_theme_mod('pid_announcement',sanitize_text_field($set['announcementText']));$message=sprintf('Imported or updated %d programme records. Review them in PID Programmes and upload the original image files to Media Library.', $count);}}}echo '<div class="wrap"><h1>PID Uganda Content Import</h1><p>Upload the original src/config/siteContent.json file from GitHub. Repeat imports update existing programme records instead of duplicating them. This does not change DNS or the live site.</p>';if($message)echo '<div class="notice notice-info"><p>'.esc_html($message).'</p></div>';echo '<form method="post" enctype="multipart/form-data">';wp_nonce_field('pid_import_content','pid_import_nonce');echo '<input type="file" name="pid_json" accept=".json,application/json" required> ';submit_button('Import PID Content','primary','submit',false);echo '</form><p>Back up WordPress first and review imported content before launch.</p></div>';}
